import fs from "node:fs";
import path from "node:path";
import { describe, expect, it, vi } from "vitest";
import { main } from "../src/cli";
import { fixturesDir, freshTmpDir, zodFixture } from "./helpers";

// Everything the CLI writes for a user (the generated files' header and
// TODO text, the spec titles, the help text) is published prose, and the
// project's voice rule bans the em dash in published prose. The header
// used to read "formstand-cli — edit freely"; it and every other emitted
// dash are reworded. One sweep over real output keeps them from coming
// back one string at a time.

const EM_DASH = "—";

const listFiles = (dir: string): readonly string[] =>
  fs
    .readdirSync(dir, { withFileTypes: true })
    .flatMap((entry) =>
      entry.isDirectory()
        ? listFiles(path.join(dir, entry.name))
        : [path.join(dir, entry.name)],
    );

const degradedFixture = path.join(fixturesDir, "recordSchema.ts");

describe("emitted prose", () => {
  it("the generated header is dash-free and the files carry no em dash", async () => {
    const dir = freshTmpDir("emitted-prose-single");
    const out = path.join(dir, "RecordForm.tsx");
    expect(await main([degradedFixture, "--ui", "mui", "--tests", "vitest", "--out", out])).toBe(0);
    const code = fs.readFileSync(out, "utf8");
    expect(code.startsWith("// Generated by formstand-cli: edit freely, this file is yours.")).toBe(true);
    listFiles(dir).forEach((file) => {
      expect(fs.readFileSync(file, "utf8")).not.toContain(EM_DASH);
    });
  });

  it("the module layout's files carry no em dash", async () => {
    const dir = freshTmpDir("emitted-prose-module");
    expect(await main([zodFixture, "--layout", "module", "--out", dir])).toBe(0);
    listFiles(dir).forEach((file) => {
      expect(fs.readFileSync(file, "utf8")).not.toContain(EM_DASH);
    });
  });

  it("the help text carries no em dash", async () => {
    const chunks: string[] = [];
    const spy = vi
      .spyOn(process.stdout, "write")
      .mockImplementation(((chunk: unknown): boolean => {
        chunks.push(String(chunk));
        return true;
      }) as typeof process.stdout.write);
    try {
      expect(await main(["--help"])).toBe(0);
    } finally {
      spy.mockRestore();
    }
    const help = chunks.join("");
    expect(help).toContain("formstand-gen: generate formstand form components");
    expect(help).not.toContain(EM_DASH);
  });
});
